{"CommandLine":"python -c "
import glob, json, re
from pathlib import Path

KV_REGEX = re.compile(r'(\w+)=(?:\"([^\"]*)\"|(\S+))')

log_dir = Path(r'C:\Users\Pavan\hackerrank-orchestrate-october26\dataset\evidence\logs')
traces_found = 0
correlated_rows = 0

for log_file in sorted(log_dir.glob('*.log')):
    # trace_id -> list of raw entries (dict)
    trace_groups = {}
    with open(log_file, 'r', encoding='utf-8', errors='ignore') as f:
        for line in f:
            line = line.strip()
            if not line: continue

            entry = {}
            j_start = line.find('{')
            if j_start != -1 and line.endswith('}'):
                try:
                    entry = json.loads(line[j_start:])
                except:
                    pass
            elif '=' in line:
                for m in KV_REGEX.findall(line):
                    k = m[0]
                    v = m[1] if m[1] != '' else m[2]
                    if v not in ('null', 'None'):
                        entry[k] = v

            trace_id = entry.get('trace_id') or entry.get('requestId')
            if trace_id:
                trace_groups.setdefault(trace_id, []).append(entry)

    traces_found += len(trace_groups)
    for tid, entries in trace_groups.items():
        # Pass 1:
        trace_email = None
        trace_user_id = None
        for e in entries:
            for k in ('lookup_key', 'subject_ref', 'subject_reference', 'email', 'customer_email', 'requester_email'):
                val = e.get(k)
                if val:
                    val = str(val).strip()
                    if '@' in val and not trace_email:
                        trace_email = val
                    if val.startswith('user_') and not trace_user_id:
                        trace_user_id = val
        if trace_email or trace_user_id:
            correlated_rows += 1

print('Total traces:', traces_found, 'Traces with identifiers:', correlated_rows)
"","WaitMsBeforeAsync":5000,"toolSummary":"Test trace correlation logic"}
